  1→/**
  2→ * WT-025 需求 2 · report-utils.ts — 报告层可复用工具（数据源无关）
  3→ *
  4→ * 抽自 perfetto-report-mvp.ts，供 perfetto / simpleperf / unity 报告脚本共用。
  5→ * 约束（不变）：
  6→ *   - 不硬编码业务名清单 / 绝对阈值 / §0-§9 死模板
  7→ *   - 数据源无关：所有函数只依赖通用接口，不依赖 Perfetto 专有类型
  8→ *   - 单态判定函数（judgeByP50Ratio / judgeByVsync）标注 draft，待 DR-42 验证后定稿
  9→ *
 10→ * 五类工具：
 11→ *   1. 子树归并：buildNameParentChains / isAncestorOf / mergeBySubtree
 12→ *   2. 人话化：humanizeRelativeJudgment / humanizeCausalInference / humanizeFoldChange
 13→ *   3. 判定（多态 + 单态统一）：detectStateMode / judgeByFoldChange / judgeByP50Ratio / judgeByVsync
 14→ *   4. 叙事：buildTopConclusionBlock / buildAsciiBar / buildSubtreeDrilldown
 15→ *   5. 渲染：renderFourPartBlock / renderDrilldownCard / renderCallTreeWithSeverity
 16→ */
 17→
 18→// ─────────────────────────── 共用类型 ───────────────────────────
 19→
 20→/**
 21→ * 通用调用树节点——数据源无关的最小接口。
 22→ * Perfetto / simpleperf / unity 的 callTree 都能适配到这个形状。
 23→ */
 24→export interface ReportTreeNode {
 25→  name: string;
 26→  totalMs?: number;
 27→  totalPct?: number;
 28→  count?: number;
 29→  children?: ReportTreeNode[];
 30→}
 31→
 32→/**
 33→ * 子树归并：name → parentChain[] 映射（DR-41 规则 2）。
 34→ * 从 callTree 动态构建，用于 top 列表的子树归并。
 35→ */
 36→export interface NameParentChain {
 37→  name: string;
 38→  parentChain: string[]; // 从 root 到该节点的祖先链（不含自身）
 39→  perFrameMs: number | null;
 40→}
 41→
 42→/**
 43→ * 相对基线（多态判定用）——与 WT-020 explore 层 RelativeBaseline 对齐。
 44→ * foldChange/deltaPct 可空（explore 层可能返回 null）。
 45→ */
 46→export interface RelativeBaseline {
 47→  baselineRole: string;
 48→  compareRole: string;
 49→  absoluteValue: string;
 50→  baselineValue: string;
 51→  foldChange?: number | null;
 52→  deltaPct?: number | null;
 53→  relativeJudgment: string;
 54→}
 55→
 56→/**
 57→ * §0 三大独立结论的图文穿插四段式块（DR-41 规则 4）。
 58→ * 每块 = 引用块结论 + 加粗一句话 + ASCII 图 + 关键数字解读。
 59→ */
 60→export interface TopConclusionBlock {
 61→  rank: number;
 62→  tag: string;          // "①" / "②" / "③"
 63→  severity: 'critical' | 'warning' | 'info';
 64→  oneLiner: string;     // 加粗一句话结论（人话，无字段名）
 65→  asciiChart: string;   // ASCII 图（柱状/缩进树/对照）
 66→  keyNumbers: string[]; // 关键数字解读，每条一行
 67→  seeAlso: string;      // "详见 §X" 引用
 68→  findingIds: string[]; // 关联 finding（仅 narrative.json 用，不渲染到 HTML 正文）
 69→}
 70→
 71→/**
 72→ * 下钻卡片数据（DR-41 规则 3 下钻详情层）。
 73→ */
 74→export interface DrilldownCard {
 75→  module: string;
 76→  mergedChildren: string[];
 77→  perFrameMs: number | null;
 78→  keyNumbers: string[];
 79→  callTreeSnippet?: string; // 可选的 callTree 缩进片段
 80→  optimization?: string;    // 可选的优化方向
 81→}
 82→
 83→// ─────────────────────────── 1. 子树归并工具 ───────────────────────────
 84→
 85→/**
 86→ * 从 callTree 动态构建 name → parentChain[] 映射（DR-41 规则 2）。
 87→ *
 88→ * 数据源无关：接收通用 ReportTreeNode，Perfetto/simpleperf/unity 的 callTree 都能用。
 89→ * frameCount 用于计算 perFrameMs（若 ≤0 则 perFrameMs=null）。
 90→ *
 91→ * 同名节点可能多次出现（不同分支），保留 parentChain 最长（最深的那个）。
 92→ */
 93→export function buildNameParentChains(
 94→  root: ReportTreeNode | undefined,
 95→  frameCount: number,
 96→): Map<string, NameParentChain> {
 97→  const result = new Map<string, NameParentChain>();
 98→  const walk = (node: ReportTreeNode | undefined, ancestors: string[]) => {
 99→    if (!node) return;
100→    const totalMs = typeof node.totalMs === 'number' ? node.totalMs : null;
101→    const perFrameMs = totalMs != null && frameCount > 0 ? totalMs / frameCount : null;
102→    const existing = result.get(node.name);
103→    if (!existing || ancestors.length > existing.parentChain.length) {
104→      result.set(node.name, {
105→        name: node.name,
106→        parentChain: [...ancestors],
107→        perFrameMs,
108→      });
109→    }
110→    if (node.children) {
111→      for (const c of node.children) walk(c, [...ancestors, node.name]);
112→    }
113→  };
114→  walk(root, []);
115→  return result;
116→}
117→
118→/**
119→ * 判断 A 是否是 B 的祖先（A 在 B 的 parentChain 里）。
120→ */
121→export function isAncestorOf(
122→  ancestorName: string,
123→  childName: string,
124→  parentChains: Map<string, NameParentChain>,
125→): boolean {
126→  if (ancestorName === childName) return false;
127→  const child = parentChains.get(childName);
128→  if (!child) return false;
129→  return child.parentChain.includes(ancestorName);
130→}
131→
132→/**
133→ * 对 top 列表做子树归并：若某节点的祖先已在列表里，跳过（或合并到祖先的 mergedChildren）。
134→ * 输入按贡献降序排列，输出保留贡献最大的祖先，child 挂在祖先的 mergedChildren 里。
135→ *
136→ * getName：从 entry 提取模块名的访问器（不同调用方用 name/module 字段名不一致）。
137→ * 归并的 child name 写回 entry 的 mergedChildren 字段（string[]）。
138→ */
139→export function mergeBySubtree<T extends Record<string, unknown>>(
140→  sortedEntries: T[],
141→  parentChains: Map<string, NameParentChain>,
142→  getName: (entry: T) => string,
143→): T[] {
144→  const result: T[] = [];
145→  for (const entry of sortedEntries) {
146→    const name = getName(entry);
147→    // 检查是否已有祖先在 result 里
148→    let mergedInto: T | null = null;
149→    for (const kept of result) {
150→      if (isAncestorOf(getName(kept), name, parentChains)) {
151→        mergedInto = kept;
152→        break;
153→      }
154→    }
155→    if (mergedInto) {
156→      // 归并：把当前 entry 的 name 加到祖先的 mergedChildren
157→      const keptChildren = (mergedInto.mergedChildren as string[] | undefined) ?? [];
158→      if (!keptChildren.includes(name)) {
159→        (mergedInto as Record<string, unknown>).mergedChildren = [...keptChildren, name];
160→      }
161→    } else {
162→      // 检查是否有后代已在 result 里——若有，把后代合并到当前 entry（当前 entry 贡献更大，应排在前）
163→      const descendantsInResult: T[] = [];
164→      for (const kept of result) {
165→        if (isAncestorOf(name, getName(kept), parentChains)) {
166→          descendantsInResult.push(kept);
167→        }
168→      }
169→      if (descendantsInResult.length > 0) {
170→        // 从 result 移除后代，合并到当前 entry
171→        const newMerged: string[] = (entry.mergedChildren as string[] | undefined) ?? [];
172→        for (const d of descendantsInResult) {
173→          const dName = getName(d);
174→          if (!newMerged.includes(dName)) newMerged.push(dName);
175→          const dChildren = (d.mergedChildren as string[] | undefined) ?? [];
176→          for (const mc of dChildren) {
177→            if (!newMerged.includes(mc)) newMerged.push(mc);
178→          }
179→        }
180→        (entry as Record<string, unknown>).mergedChildren = newMerged;
181→        const descNames = new Set(descendantsInResult.map((d) => getName(d)));
182→        // 从 result 里移除后代
183→        for (let i = result.length - 1; i >= 0; i--) {
184→          if (descNames.has(getName(result[i]))) result.splice(i, 1);
185→        }
186→        result.push(entry);
187→      } else {
188→        result.push(entry);
189→      }
190→    }
191→  }
192→  return result;
193→}
194→
195→// ─────────────────────────── 2. 人话化工具 ───────────────────────────
196→
197→/**
198→ * 把 relativeBaseline 转成人话（去字段名）。
199→ * foldChange=9999 sentinel → "仅在 X 出现（Y 无此节点）"。
200→ */
201→export function humanizeRelativeJudgment(rb: RelativeBaseline | undefined): string {
202→  if (!rb) return '';
203→  const fc = rb.foldChange;
204→  if (fc != null && fc >= 9999) {
205→    return `仅在 ${rb.compareRole} 出现（${rb.baselineRole} 无此节点）`;
206→  }
207→  if (fc != null && Number.isFinite(fc)) {
208→    if (fc > 1) {
209→      return `${rb.baselineRole} → ${rb.compareRole} 涨 ×${fc.toFixed(2)}`;
210→    } else if (fc < 1) {
211→      return `${rb.baselineRole} → ${rb.compareRole} 降 ×${fc.toFixed(2)}`;
212→    }
213→    return `${rb.baselineRole} → ${rb.compareRole} 持平`;
214→  }
215→  // 退化用原 relativeJudgment 但去掉字段名
216→  return rb.relativeJudgment
217→    .replace(/foldChange=9999 sentinel\)?/g, '新增路径')
218→    .replace(/foldChange=[\d.]+/g, (m) => `×${m.replace('foldChange=', '')}`);
219→}
220→
221→/**
222→ * 把因果推理 inference 字符串转成人话（去 effectiveCoveragePct / maxWaitSlice / sleepingMs 等字段名）。
223→ */
224→export function humanizeCausalInference(inference: string): string {
225→  return inference
226→    .replace(/effectiveCoveragePct[≈=]([\d.]+)%?\s*\(maxWait\/sleepingMs\)/g, '主线程睡的时候约 $1% 在等该 wait slice')
227→    .replace(/effectiveCoveragePct[≈=]([\d.]+)%?/g, '主线程睡的时候约 $1% 在等该 wait slice')
228→    .replace(/maxWaitSlice=([^;]+)/g, '$1')
229→    .replace(/sleepingMs=([\d.]+)/g, 'Sleep $1ms')
230→    .replace(/byState\.S\.totalMs/g, 'Sleeping 累计')
231→    .replace(/nested sum coveragePct=[\d.]+%.*?(?=;|→|$)/g, '')
232→    .replace(/\(\s*—\s*use max not sum\s*\)/g, '');
233→}
234→
235→/**
236→ * 把 foldChange 数值转成人话："新增" / "×N" / "持平"。
237→ * 用于 ROI rationale 等需要简短描述的场景。
238→ */
239→export function humanizeFoldChange(fc: number | undefined): string {
240→  if (fc == null) return '—';
241→  if (fc >= 9999) return '新增';
242→  if (!Number.isFinite(fc)) return '—';
243→  if (fc > 1) return `×${fc.toFixed(2)}`;
244→  if (fc < 1) return `×${fc.toFixed(2)}`;
245→  return '持平';
246→}
247→
248→// ─────────────────────────── 3. 判定工具（多态 + 单态统一）───────────────────────────
249→
250→/**
251→ * 检测报告是单态还是多态。
252→ * - 'multi'：有 ≥2 个态可对比（如 base/cur/throttle）
253→ * - 'single'：只有 1 个态（如 simpleperf/unity 单源）
254→ *
255→ * summaries 长度即态数。空数组视为 single（退化）。
256→ */
257→export function detectStateMode(summaries: unknown[]): 'single' | 'multi' {
258→  return summaries.length >= 2 ? 'multi' : 'single';
259→}
260→
261→/**
262→ * 多态判定：用 foldChange 判定是否为热点涨幅。
263→ * threshold 为相对倍数阈值（如 2.0 = 涨 2 倍以上算热点）。
264→ * foldChange=9999 sentinel 视为新增路径（强信号）。
265→ */
266→export function judgeByFoldChange(fc: number | undefined, threshold: number): 'new' | 'rise' | 'flat' | 'drop' {
267→  if (fc == null) return 'flat';
268→  if (fc >= 9999) return 'new';
269→  if (!Number.isFinite(fc)) return 'flat';
270→  if (fc > threshold) return 'rise';
271→  if (fc < 1 / threshold) return 'drop';
272→  return 'flat';
273→}
274→
275→/**
276→ * 单态判定（DR-42 draft）：用 perFrameMs 占 p50 的百分比判定是否为热点。
277→ * 例如 perFrameMs=8ms, p50Ms=30ms → ratio=26.7%，若 threshold=20% 则判 'hot'。
278→ *
279→ * // draft, pending DR-42 validation
280→ * 待 simpleperf / unity 单源验证后定稿。
281→ */
282→export function judgeByP50Ratio(
283→  perFrameMs: number | null,
284→  p50Ms: number | null,
285→  threshold: number, // 占比阈值，如 0.2 = 20%
286→): 'hot' | 'normal' | 'unknown' {
287→  if (perFrameMs == null || p50Ms == null || p50Ms <= 0) return 'unknown';
288→  const ratio = perFrameMs / p50Ms;
289→  if (ratio >= threshold) return 'hot';
290→  return 'normal';
291→}
292→
293→/**
294→ * 单态判定（DR-42 draft）：用单次耗时 vs vsync 周期判定 GPU-bound。
295→ * 例如 avgMs=18ms, vsyncMs=16.66ms → ratio=1.08，若 threshold=1.0 则判 'gpu-bound'。
296→ *
297→ * // draft, pending DR-42 validation
298→ * 待 simpleperf / unity 单源验证后定稿。
299→ */
300→export function judgeByVsync(
301→  avgMs: number | null,
302→  vsyncMs: number | null,
303→  threshold: number, // 比值阈值，如 1.0 = 单次耗时 ≥ vsync 周期
304→): 'gpu-bound' | 'normal' | 'unknown' {
305→  if (avgMs == null || vsyncMs == null || vsyncMs <= 0) return 'unknown';
306→  const ratio = avgMs / vsyncMs;
307→  if (ratio >= threshold) return 'gpu-bound';
308→  return 'normal';
309→}
310→
311→// ─────────────────────────── 4. 叙事工具 ───────────────────────────
312→
313→/**
314→ * 构建 ASCII 柱状图：value/max 映射到 width 个 █/░ 字符。
315→ */
316→export function buildAsciiBar(value: number, max: number, width = 20): string {
317→  const w = Math.max(0, Math.min(width, Math.round((value / max) * width)));
318→  return '█'.repeat(w) + '░'.repeat(Math.max(0, width - w));
319→}
320→
321→/**
322→ * 构建单个 TopConclusionBlock（DR-41 规则 4 四段式）。
323→ * 调用方负责组织 rank/tag/severity/oneLiner/asciiChart/keyNumbers/seeAlso 的语义，
324→ * 本函数只做组装——这样不同数据源可以用各自的逻辑生成内容，共用同一个块结构。
325→ */
326→export function buildTopConclusionBlock(params: {
327→  rank: number;
328→  tag: string;
329→  severity: 'critical' | 'warning' | 'info';
330→  oneLiner: string;
331→  asciiChart: string;
332→  keyNumbers: string[];
333→  seeAlso: string;
334→  findingIds: string[];
335→}): TopConclusionBlock {
336→  return {
337→    rank: params.rank,
338→    tag: params.tag,
339→    severity: params.severity,
340→    oneLiner: params.oneLiner,
341→    asciiChart: params.asciiChart,
342→    keyNumbers: params.keyNumbers,
343→    seeAlso: params.seeAlso,
344→    findingIds: params.findingIds,
345→  };
346→}
347→
348→/**
349→ * 构建子树下钻结构（DR-41 规则 3 下钻详情层）。
350→ * 主入口 → 子树 → 红线模块三层。
351→ *
352→ * 从 callTree 提取指定 module 子树下的 top N 子节点（按 totalMs 降序），
353→ * 用于下钻详情卡片。
354→ */
355→export function buildSubtreeDrilldown(
356→  module: string,
357→  root: ReportTreeNode | undefined,
358→  topN: number,
359→): { module: string; children: Array<{ name: string; totalMs: number | null; perFrameMs: number | null }> } {
360→  const children: Array<{ name: string; totalMs: number | null; perFrameMs: number | null }> = [];
361→  if (!root) return { module, children };
362→
363→  // 找到 module 节点
364→  let target: ReportTreeNode | null = null;
365→  const find = (n: ReportTreeNode | undefined) => {
366→    if (!n || target) return;
367→    if (n.name === module) { target = n; return; }
368→    if (n.children) for (const c of n.children) find(c);
369→  };
370→  find(root);
371→  if (!target?.children) return { module, children };
372→
373→  // 收集子节点，按 totalMs 降序
374→  const sorted = [...target.children]
375→    .map((c) => ({
376→      name: c.name,
377→      totalMs: typeof c.totalMs === 'number' ? c.totalMs : null,
378→      perFrameMs: null,
379→    }))
380→    .sort((a, b) => (b.totalMs ?? 0) - (a.totalMs ?? 0));
381→
382→  return { module, children: sorted.slice(0, topN) };
383→}
384→
385→// ─────────────────────────── 5. 渲染工具 ───────────────────────────
386→
387→/**
388→ * HTML 转义。
389→ */
390→export function htmlEsc(s: unknown): string {
391→  if (s == null) return '';
392→  return String(s)
393→    .replace(/&/g, '&amp;')
394→    .replace(/</g, '&lt;')
395→    .replace(/>/g, '&gt;')
396→    .replace(/"/g, '&quot;')
397→    .replace(/'/g, '&#39;');
398→}
399→
400→/**
401→ * 渲染四段式块 HTML（DR-41 规则 4：引用块 + ASCII 图 + 关键数字 + 详见 §X）。
402→ * 数据源无关：只依赖 TopConclusionBlock 结构。
403→ */
404→export function renderFourPartBlock(block: TopConclusionBlock, sevClass: (sev: string) => string): string {
405→  return `
406→    <div class="card conclusion-block ${sevClass(block.severity)}">
407→      <div class="block-tag">${htmlEsc(block.tag)}</div>
408→      <div class="block-body">
409→        <blockquote class="one-liner"><strong>${htmlEsc(block.oneLiner)}</strong></blockquote>
410→        <pre class="ascii">${htmlEsc(block.asciiChart)}</pre>
411→        <ul class="key-numbers">
412→          ${block.keyNumbers.map((k) => `<li>${htmlEsc(k)}</li>`).join('\n')}
413→        </ul>
414→        <p class="see-also">${htmlEsc(block.seeAlso)}</p>
415→      </div>
416→    </div>`;
417→}
418→
419→/**
420→ * 渲染下钻卡片 HTML（DR-41 规则 3 下钻详情层）。
421→ * 数据源无关：只依赖 DrilldownCard 结构。
422→ */
423→export function renderDrilldownCard(card: DrilldownCard): string {
424→  const mergedNote = card.mergedChildren.length > 0
425→    ? `<p class="muted small">子树归并：${card.mergedChildren.map(htmlEsc).join(' / ')}</p>`
426→    : '';
427→  const perFrameLine = card.perFrameMs != null
428→    ? `<p>ms/帧：<strong>${card.perFrameMs.toFixed(2)}</strong></p>`
429→    : '';
430→  const keyNumberList = card.keyNumbers.length > 0
431→    ? `<ul class="key-numbers">${card.keyNumbers.map((k) => `<li>${htmlEsc(k)}</li>`).join('')}</ul>`
432→    : '';
433→  const callTreeLine = card.callTreeSnippet
434→    ? `<pre class="ascii">${htmlEsc(card.callTreeSnippet)}</pre>`
435→    : '';
436→  const optLine = card.optimization
437→    ? `<p class="note">${htmlEsc(card.optimization)}</p>`
438→    : '';
439→  return `
440→    <div class="card drilldown">
441→      <h4>${htmlEsc(card.module)}</h4>
442→      ${mergedNote}
443→      ${perFrameLine}
444→      ${keyNumberList}
445→      ${callTreeLine}
446→      ${optLine}
447→    </div>`;
448→}
449→
450→/**
451→ * 渲染带严重程度标注的 callTree 缩进树（🔴/🟡/🟢/📈/[wrapper]）。
452→ * 数据源无关：接收通用 ReportTreeNode。
453→ *
454→ * severityOf：节点名 → 严重程度的回调（由调用方根据 findings/红线判定提供）。
455→ *   返回 'critical' | 'warning' | 'info' | 'wrapper' | null（null=不标注）
456→ */
457→export function renderCallTreeWithSeverity(
458→  root: ReportTreeNode | undefined,
459→  severityOf: (name: string) => 'critical' | 'warning' | 'info' | 'wrapper' | null,
460→  maxDepth: number,
461→): string {
462→  if (!root) return '';
463→  const lines: string[] = [];
464→  const sevMark = (s: 'critical' | 'warning' | 'info' | 'wrapper' | null): string => {
465→    if (s === 'critical') return ' 🔴';
466→    if (s === 'warning') return ' 🟡';
467→    if (s === 'info') return ' 🟢';
468→    if (s === 'wrapper') return ' [wrapper]';
469→    return '';
470→  };
471→  const walk = (n: ReportTreeNode, depth: number, prefix: string) => {
472→    if (depth > maxDepth) return;
473→    const ms = typeof n.totalMs === 'number' ? ` (${n.totalMs.toFixed(2)}ms)` : '';
474→    lines.push(`${prefix}${n.name}${ms}${sevMark(severityOf(n.name))}`);
475→    if (n.children) {
476→      for (let i = 0; i < n.children.length; i++) {
477→        const last = i === n.children.length - 1;
478→        walk(n.children[i], depth + 1, prefix + (last ? '  ' : '  '));
479→      }
480→    }
481→  };
482→  walk(root, 0, '');
483→  return lines.join('\n');
484→}
485→

  1→/**
  2→ * tools.test.ts — Prism B2 query tool layer test script
  3→ *
  4→ * Plain tsx script (no test runner). Run from web/ directory:
  5→ *   npx tsx server/prism/tools.test.ts
  6→ *
  7→ * Prints PASS/FAIL for each assertion; exits non-zero on any failure.
