import {
  gcAllocToPerFrame,
  buildTriadAsciiBar,
  buildStateDistributionAscii,
  renderCallTreeTriad,
  renderSubtreeDrilldown,
} from './report-utils.js';

// 测试 GC 归因换算
const gpf = gcAllocToPerFrame(5341, 484);
console.log('GC perFrame:', gpf, '(期望 11.0)');

// 测试三态 ASCII 柱状图
const triad = buildTriadAsciiBar(
  [{ role: 'base', value: 86.94 }, { role: 'cur', value: 77.82 }, { role: 'throttle', value: 56.99 }],
  100, 'Run',
);
console.log('--- TriadAsciiBar ---');
console.log(triad);

// 测试状态分布 ASCII
const dist = buildStateDistributionAscii(
  [
    { role: 'base', runPct: 86.94, sleepPct: 12.04, runnablePct: 0.97 },
    { role: 'cur', runPct: 77.82, sleepPct: 20.40, runnablePct: 1.62 },
    { role: 'throttle', runPct: 56.99, sleepPct: 38.99, runnablePct: 2.83 },
  ],
  { base: '凉机 CPU-bound 健康', cur: '算+等混合', throttle: '半睡型 GPU-bound' },
);
console.log('--- StateDistributionAscii ---');
console.log(dist);

// 测试 callTree ├─/└─ 三态对照
const tree = {
  name: 'PlayerLoop',
  children: [
    { name: 'URP.Render', children: [
      { name: 'URP.AfterRendering', children: [
        { name: 'URP.Submit' },
      ] },
      { name: 'URP.MainRenderingTransparent' },
    ] },
    { name: 'Core.Update', children: [
      { name: 'CS:AOE.LuaMgr' },
      { name: 'CS:AOE.Outside.MapManager' },
    ] },
  ],
};
const triadMap = {
  base: new Map([['PlayerLoop', 16.72], ['URP.Render', 6.88], ['URP.AfterRendering', 1.68], ['Core.Update', 1.73], ['CS:AOE.LuaMgr', 1.00]]),
  cur: new Map([['PlayerLoop', 30.18], ['URP.Render', 13.09], ['URP.AfterRendering', 6.84], ['Core.Update', 7.32], ['CS:AOE.LuaMgr', 3.80]]),
  throttle: new Map([['PlayerLoop', 46.68], ['URP.Render', 26.04], ['URP.AfterRendering', 19.33], ['Core.Update', 8.05], ['CS:AOE.LuaMgr', 3.47]]),
};
const sev = (n: string): 'critical' | 'warning' | 'info' | 'wrapper' | 'wait' | null => {
  if (n === 'URP.AfterRendering') return 'critical';
  if (n === 'URP.Submit') return 'wait';
  if (n === 'URP.Render') return 'wrapper';
  return null;
};
const callTreeStr = renderCallTreeTriad(tree, triadMap, sev, 5);
console.log('--- CallTreeTriad ---');
console.log(callTreeStr);

// 测试树状下钻（按贡献度排序）
const drilldown = renderSubtreeDrilldown(tree, triadMap, sev, 3, 'cur');
console.log('--- SubtreeDrilldown (sorted by cur) ---');
console.log(drilldown);

// 单态退化测试
const singleMap = { single: new Map([['PlayerLoop', 30.18], ['URP.Render', 13.09]]) };
const singleTree = renderCallTreeTriad(tree, singleMap, () => null, 2);
console.log('--- Single-state CallTreeTriad ---');
console.log(singleTree);

// null 值测试
const gpfNull = gcAllocToPerFrame(100, 0);
console.log('GC perFrame (frameCount=0):', gpfNull, '(期望 null)');
